import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// C[row] = sum_k A[row, k] * B[k]
// Four-way split-K: four blocks per row each reduce a disjoint quarter
// of K with the original four-wave register blocking, then atomically
// accumulate their partial sums into C.
.visible .entry matvec_kernel(
    .param .u64 pA,
    .param .u64 pB,
    .param .u64 pC,
    .param .u32 pM,
    .param .u32 pK
)
{
    .reg .pred  %p<8>;
    .reg .b32   %r<24>;
    .reg .b64   %rd<32>;
    .reg .f32   %f<40>;
    .shared .align 4 .b8 warp_sums[128];
    ld.param.u64 %rd0, [pA];            // A base
    ld.param.u64 %rd1, [pB];            // B base
    ld.param.u64 %rd2, [pC];            // C base
    ld.param.u32 %r0,  [pM];            // M
    ld.param.u32 %r1,  [pK];            // K
    mov.u32 %r2, %ctaid.x;
    shr.u32 %r2, %r2, 2;                // row = block / 4
    setp.ge.u32 %p0, %r2, %r0;
    @%p0 bra EXIT;                      // bounds check on row
    mov.u32 %r3, %tid.x;                // thread id
    mov.u32 %r18, %ctaid.x;
    and.b32 %r18, %r18, 3;              // split id = block % 4
    shr.u32 %r17, %r1, 2;               // K / 4
    and.b32 %r19, %r1, 3;
    setp.ne.u32 %p1, %r19, 0;
    @%p1 add.u32 %r17, %r17, 1;         // ceil(K / 4)
    mul.lo.u32 %r12, %r18, %r17;        // split start
    add.u32 %r16, %r12, %r17;           // split end
    setp.le.u32 %p1, %r16, %r1;
    @%p1 bra RANGE_READY;
    mov.u32 %r16, %r1;                  // clamp end to K
RANGE_READY:
    mul.wide.u32 %rd3, %r2, %r1;        // row * K (elements)
    shl.b64 %rd3, %rd3, 2;              // row * K * 4 (bytes)
    add.u64 %rd4, %rd0, %rd3;           // &A[row][0]
    shl.b32 %r4, %r3, 2;                // tid * 4 (elements)
    mov.u32 %r5, %ntid.x;
    shl.b32 %r5, %r5, 2;                // wave stride = blockDim.x * 4
    mov.u32 %r13, 4096;                 // 4 waves * 256 threads * 4 elems
    mov.f32 %f0, 0f00000000;
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.f32 %f3, 0f00000000;
MAIN_LOOP:
    add.u32 %r14, %r12, %r13;
    setp.gt.u32 %p0, %r14, %r16;        // base+4096 > end -> remainder
    @%p0 bra REM_SETUP;
    add.u32 %r15, %r12, %r4;            // first element for this thread
    mul.wide.u32 %rd5, %r15, 4;         // byte offset of chunk 0
    add.u64 %rd6, %rd4, %rd5;           // A chunk 0
    add.u64 %rd7, %rd1, %rd5;           // B chunk 0
    add.u64 %rd8, %rd6, 4096;           // A chunk 1
    add.u64 %rd9, %rd7, 4096;           // B chunk 1
    add.u64 %rd10, %rd6, 8192;          // A chunk 2
    add.u64 %rd11, %rd7, 8192;          // B chunk 2
    add.u64 %rd12, %rd6, 12288;         // A chunk 3
    add.u64 %rd13, %rd7, 12288;         // B chunk 3
    ld.global.nc.v4.f32 {%f4,%f5,%f6,%f7},     [%rd6];
    ld.global.nc.v4.f32 {%f8,%f9,%f10,%f11},   [%rd7];
    ld.global.nc.v4.f32 {%f12,%f13,%f14,%f15}, [%rd8];
    ld.global.nc.v4.f32 {%f16,%f17,%f18,%f19}, [%rd9];
    ld.global.nc.v4.f32 {%f20,%f21,%f22,%f23}, [%rd10];
    ld.global.nc.v4.f32 {%f24,%f25,%f26,%f27}, [%rd11];
    ld.global.nc.v4.f32 {%f28,%f29,%f30,%f31}, [%rd12];
    ld.global.nc.v4.f32 {%f32,%f33,%f34,%f35}, [%rd13];
    fma.rn.f32 %f0, %f4,  %f8,  %f0;
    fma.rn.f32 %f1, %f5,  %f9,  %f1;
    fma.rn.f32 %f2, %f6,  %f10, %f2;
    fma.rn.f32 %f3, %f7,  %f11, %f3;
    fma.rn.f32 %f0, %f12, %f16, %f0;
    fma.rn.f32 %f1, %f13, %f17, %f1;
    fma.rn.f32 %f2, %f14, %f18, %f2;
    fma.rn.f32 %f3, %f15, %f19, %f3;
    fma.rn.f32 %f0, %f20, %f24, %f0;
    fma.rn.f32 %f1, %f21, %f25, %f1;
    fma.rn.f32 %f2, %f22, %f26, %f2;
    fma.rn.f32 %f3, %f23, %f27, %f3;
    fma.rn.f32 %f0, %f28, %f32, %f0;
    fma.rn.f32 %f1, %f29, %f33, %f1;
    fma.rn.f32 %f2, %f30, %f34, %f2;
    fma.rn.f32 %f3, %f31, %f35, %f3;
    add.u32 %r12, %r12, %r13;
    bra MAIN_LOOP;
REM_SETUP:
    add.u32 %r4, %r4, %r12;             // absolute element index
VEC_LOOP:
    setp.ge.u32 %p0, %r4, %r16;         // idx >= end -> done
    @%p0 bra COMBINE;
    add.u32 %r6, %r4, 4;
    setp.gt.u32 %p1, %r6, %r16;         // idx+4 > end -> scalar tail
    @%p1 bra TAIL_LOOP;
    mul.wide.u32 %rd5, %r4, 4;          // byte offset
    add.u64 %rd6, %rd4, %rd5;           // &A[row][idx]
    add.u64 %rd7, %rd1, %rd5;           // &B[idx]
    ld.global.nc.v4.f32 {%f4,%f5,%f6,%f7},  [%rd6];
    ld.global.nc.v4.f32 {%f8,%f9,%f10,%f11}, [%rd7];
    fma.rn.f32 %f0, %f4, %f8,  %f0;
    fma.rn.f32 %f1, %f5, %f9,  %f1;
    fma.rn.f32 %f2, %f6, %f10, %f2;
    fma.rn.f32 %f3, %f7, %f11, %f3;
    add.u32 %r4, %r4, %r5;
    bra VEC_LOOP;
TAIL_LOOP:
    setp.ge.u32 %p0, %r4, %r16;
    @%p0 bra COMBINE;
    mul.wide.u32 %rd5, %r4, 4;
    add.u64 %rd6, %rd4, %rd5;
    add.u64 %rd7, %rd1, %rd5;
    ld.global.nc.f32 %f4, [%rd6];
    ld.global.nc.f32 %f8, [%rd7];
    fma.rn.f32 %f0, %f4, %f8, %f0;
    add.u32 %r4, %r4, 1;
    bra TAIL_LOOP;
COMBINE:
    add.f32 %f0, %f0, %f1;
    add.f32 %f2, %f2, %f3;
    add.f32 %f0, %f0, %f2;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 16, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 8, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 4, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 2, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 1, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    and.b32 %r7, %r3, 31;               // lane id
    shr.u32 %r8, %r3, 5;                // warp id
    setp.eq.u32 %p0, %r7, 0;
    @!%p0 bra AFTER_STORE;
    mov.u64 %rd8, warp_sums;
    mul.wide.u32 %rd9, %r8, 4;
    add.u64 %rd8, %rd8, %rd9;
    st.shared.f32 [%rd8], %f0;
AFTER_STORE:
    bar.sync 0;
    setp.ne.u32 %p0, %r8, 0;
    @%p0 bra EXIT;
    mov.u32 %r9, %ntid.x;
    shr.u32 %r9, %r9, 5;                // number of warps
    mov.f32 %f0, 0f00000000;
    setp.lt.u32 %p1, %r7, %r9;
    @!%p1 bra FINAL_REDUCE;
    mov.u64 %rd8, warp_sums;
    mul.wide.u32 %rd9, %r7, 4;
    add.u64 %rd8, %rd8, %rd9;
    ld.shared.f32 %f0, [%rd8];
FINAL_REDUCE:
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 16, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 8, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 4, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 2, 0x1f, 0xffffffff;
