    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M, K = A.shape
        C = torch.zeros((M, 1), dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        module.launch(
            "matvec_kernel",
            grid=(M * 4, 1, 1),
            block=(256, 1, 1),
            arguments=[A, B, C, u32(M), u32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

